    m.insert("custom_text".into(), iface_payment_links__resource_custom_text__to_json(&p.custom_text));
    m.insert("customer_creation".into(), Value::String(iface_payment_links__payment_link_customer_creation_enum__to_str(&p.customer_creation).into()));
    m.insert("id".into(), Value::String((&p.id).clone()));
    m.insert("invoice_creation".into(), match (&p.invoice_creation) { Some(v) => Value::String((v).clone()), None => Value::Null });
    m.insert("line_items".into(), match (&p.line_items) { Some(v) => iface_payment_links__payment_link_line_items__to_json(v), None => Value::Null });
    m.insert("livemode".into(), Value::Bool(*(&p.livemode)));
    m.insert("metadata".into(), iface_payment_links__payment_link_metadata__to_json(&p.metadata));
    m.insert("object".into(), Value::String(iface_payment_links__payment_link_object_enum__to_str(&p.object).into()));
    m.insert("on_behalf_of".into(), match (&p.on_behalf_of) { Some(v) => Value::String((v).clone()), None => Value::Null });
    m.insert("payment_intent_data".into(), match (&p.payment_intent_data) { Some(v) => Value::String((v).clone()), None => Value::Null });
    m.insert("payment_method_collection".into(), Value::String(iface_payment_links__payment_link_customer_creation_enum__to_str(&p.payment_method_collection).into()));
    m.insert("payment_method_types".into(), match (&p.payment_method_types) { Some(v) => Value::Array((v).iter().map(|v| Value::String(iface_payment_links__payment_link_payment_method_types_item_enum__to_str(v).into())).collect()), None => Value::Null });
    m.insert("phone_number_collection".into(), iface_payment_links__resource_phone_number_collection__to_json(&p.phone_number_collection));
