    m.insert("shipping_options".into(), Value::Array((&p.shipping_options).iter().map(|v| iface_payment_links__resource_shipping_option__to_json(v)).collect()));
    m.insert("submit_type".into(), Value::String(iface_payment_links__payment_link_submit_type_enum__to_str(&p.submit_type).into()));
